const DEFAULT_ICON = "default.png";
const LIGHT_THEME_ICON = "dark.png";
const DARK_THEME_ICON = "light.png";

add_task(async function test_theme_icons() {
  const extension = ExtensionTestUtils.loadExtension({
    useAddonManager: "temporary",
    manifest: {
      applications: {
        gecko: {
          id: "browser_action_properties@mochi.test",
        },
      },
      browser_action: {
        default_title: "default",
        default_icon: DEFAULT_ICON,
        theme_icons: [
          {
            dark: DARK_THEME_ICON,
            light: LIGHT_THEME_ICON,
            size: 16,
          },
        ],
      },
    },
  });

  const unifiedToolbarUpdate = TestUtils.topicObserved(
    "unified-toolbar-state-change"
  );
  await extension.startup();
  await unifiedToolbarUpdate;
  await TestUtils.waitForCondition(
    () =>
      document.querySelector(
        `#unifiedToolbarContent [extension="browser_action_properties@mochi.test"]`
      ),
    "Button added to unified toolbar"
  );

  const uuid = extension.uuid;
  const icon = document.querySelector(
    `#unifiedToolbarContent [extension="browser_action_properties@mochi.test"] .button-icon`
  );
  const defaultIcon = `url("moz-extension://${uuid}/default.png")`;

  const dark_theme = ExtensionTestUtils.loadExtension({
    manifest: {
      theme: {
        colors: {
          frame: "#000",
          tab_background_text: "#FFF",
        },
      },
    },
  });
  await Promise.all([
    BrowserTestUtils.waitForEvent(window, "windowlwthemeupdate"),
    dark_theme.startup(),
  ]);
  await new Promise(resolve => requestAnimationFrame(resolve));
  Assert.equal(
    window.getComputedStyle(icon).content,
    makeIconSet(
      `url("moz-extension://${uuid}/${DARK_THEME_ICON}")`,
      defaultIcon
    ),
    `Dark theme should use light icon.`
  );

  const light_theme = ExtensionTestUtils.loadExtension({
    manifest: {
      theme: {
        colors: {
          frame: "#FFF",
          tab_background_text: "#000",
        },
      },
    },
  });
  await Promise.all([
    dark_theme.unload(),
    BrowserTestUtils.waitForEvent(window, "windowlwthemeupdate"),
    light_theme.startup(),
  ]);
  await new Promise(resolve => requestAnimationFrame(resolve));
  Assert.equal(
    window.getComputedStyle(icon).content,
    makeIconSet(
      `url("moz-extension://${uuid}/${LIGHT_THEME_ICON}")`,
      defaultIcon
    ),
    `Light theme should use dark icon.`
  );

  // Disabling a theme will enable the default theme.
  await Promise.all([
    BrowserTestUtils.waitForEvent(window, "windowlwthemeupdate"),
    light_theme.unload(),
  ]);
  Assert.equal(
    makeIconSet(`url("moz-extension://${uuid}/${DEFAULT_ICON}")`, defaultIcon),
    makeIconSet(defaultIcon),
    `Default theme should use default icon.`
  );
  await extension.unload();
});

const LIGHT_THEME_ICON_16 = "dark16.png";
const LIGHT_THEME_ICON_32 = "dark32.png";
const DARK_THEME_ICON_16 = "light16.png";
const DARK_THEME_ICON_32 = "light32.png";

add_task(async function test_theme_icons_messagewindow() {
  const messageWindow = await openMessageInWindow(gMessages.getNext());
  const extension = ExtensionTestUtils.loadExtension({
    useAddonManager: "temporary",
    manifest: {
      applications: {
        gecko: {
          id: "browser_action_properties@mochi.test",
        },
      },
      browser_action: {
        default_title: "default",
        default_icon: DEFAULT_ICON,
        default_windows: ["messageDisplay"],
        theme_icons: [
          {
            dark: DARK_THEME_ICON_16,
            light: LIGHT_THEME_ICON_16,
            size: 16,
          },
          {
            dark: DARK_THEME_ICON_32,
            light: LIGHT_THEME_ICON_32,
            size: 32,
          },
        ],
      },
    },
  });

  await extension.startup();

  const uuid = extension.uuid;
  const button = messageWindow.document.getElementById(
    "browser_action_properties_mochi_test-browserAction-toolbarbutton"
  );

  await testThemeIcons(button, uuid);

  await extension.unload();
  messageWindow.close();
});
